  "indicator_readings": [
    {
      "indicator": "MM20",
      "reading": "MM20 próximo ao preço, inclinando-se levemente para baixo no curtíssimo prazo.",
      "interpretation": "Perda de impulso de curtíssimo prazo; preço já testou/ficou abaixo da MM20 nas últimas sessões."
    },
    {
      "indicator": "MM50",
      "reading": "MM50 em tendência ascendente, atuando como suporte dinâmico de médio prazo (próximo a R$10,0).",
      "interpretation": "Mantém a tendência de médio prazo; fechamento sustentado abaixo dela aumentaria probabilidade de correção mais profunda."
    },
    {
      "indicator": "MM200",
      "reading": "MM200 levemente ascendente e bem abaixo do preço atual.",
      "interpretation": "Tendência de longo prazo ainda positiva — zona de suporte estrutural mais relevante."
    },
    {
      "indicator": "EMA9",
      "reading": "EMA9 virou para baixo e cruzou a EMA21 nas últimas sessões.",
      "interpretation": "Sinal de reversão de curto prazo; confirma enfraquecimento do impulso comprador."
    },
    {
      "indicator": "EMA21",
      "reading": "EMA21 acompanha EMA9 e apresenta inclinação neutra a levemente descendente.",
      "interpretation": "Confirma contexto de curto prazo mais cauteloso."
    },
    {
      "indicator": "MACD",
      "reading": "MACD cruzou abaixo da linha de sinal; histograma em vermelho recentemente.",
      "interpretation": "Momentum virou para os vendedores no curto prazo — confirma viés de correção."
    },
    {
      "indicator": "Bollinger (20,2σ)",
      "reading": "Bandas alargadas durante o rali; preço saiu da banda superior e retornou à média.",
      "interpretation": "Volatilidade aumentada; movimento de correção após sobrecompra relativa."
    },
    {
      "indicator": "RSI14",
      "reading": "RSI caiu de níveis próximos a 70 para cerca de 40.",
      "interpretation": "Perda de força relativa; ainda não em sobrevenda extrema, mas indica fraqueza de curto prazo."
    },
    {
      "indicator": "Volume",
      "reading": "Queda recente acompanhada por aumento de volume (pico nas últimas sessões).",
      "interpretation": "Movimento de baixa com confirmação por volume — aumento da probabilidade de continuação da correção se o volume permanecer alto."
    }
  ]
}
